void FillSafe(Span<byte> data)
{
    // Many modern APIs accept Span instead of byte*
    data.Fill(0xFF);
}

public static unsafe void CopyToNative(ReadOnlySpan<byte> source, byte* dest, int len)
{
    fixed (byte* p = source)
    {
        Buffer.MemoryCopy(p, dest, len, len);
    } // p invalid after block — same as detached ArrayBuffer
}

